/**
 * Shows a hover tooltip for palette entries, displaying the entry `title`
 * and, if the entry provides one, its keyboard `shortcut`.
 *
 */
export default class PaletteTooltip {
  static $inject: string[];

  /**
   * @param eventBus
   * @param palette
   * @param hoverTooltip
   */
  constructor(eventBus: EventBus, palette: Palette, hoverTooltip: HoverTooltip);
}

type EventBus = import("../../core/EventBus").default;
type Palette = import("./Palette").default;
type HoverTooltip = import("../hover-tooltip/HoverTooltip").default;